from common import *
import shutil, platform, importlib.metadata, datetime

def main():
    assert not BASE.exists()
    import pandas as pd,numpy,lightgbm,qlib
    assert Path(qlib.__file__).resolve().is_relative_to(ROOT)
    previous=harness_previous_status()
    assert previous['status']=='closed' and len(previous['jobs'])==35
    qlib.init(provider_uri=str(PROVIDER),region='cn',kernels=1)
    from qlib.data import D
    version=str(pd.Timestamp(D.calendar(start_time='2020-01-01')[-1]).date())
    assert version=='2026-11-03'
    for p in ['configs','docs','data','metrics','reports','source-records']:(BASE/p).mkdir(parents=True)
    shutil.copy2(PREVIOUS/'configs/evaluation.yaml',BASE/'configs/evaluation.yaml')
    prior=read(PREVIOUS/'configs/frozen-study.json')
    study={**prior,'hypothesis':'Only vary equal-count bin number n. Test whether finer bins improve head return monotonically or an intermediate n balances return and label sensitivity; compare return, Sharpe, RankIC and Top3/Top5 agreement separately.','user_idea':'那在等样本上，再做几组n的实验，预估实验时间9-10小时','candidates':[{'id':v,'bins':int(v.removeprefix('quantile')),'method':'daily percentile boundaries k/n; preserve ties; exact rational midpoint-rank comparisons'} for v in VARIANTS],'sensitivity':'All five seeds per new n. Refit old-label treatment only when encoded float32 target differs; exact input identity is a reuse diagnostic, not an independent replicate.','decision_rule':'No automatic promotion. Compare each n against same-source continuous H20 and prior n5/n10. Report non-monotonicity, plateau/interior or endpoint optima separately for net_ann/Sharpe and sensitivity, including all tied maxima. Historical selection window, not independent OOS.','budget':{'max_scientific_candidates':6,'nominal_primary_fits':30,'conditional_paired_fits':20,'max_model_fits_including_retries':52,'max_wall_hours':10,'concurrency':1,'closeout_reserve_seconds':2700},'prior_research_fit_cost':PRIOR_FITS,'entry_policy':'One new study entry linked to the closed label-grading campaign. Six internal n candidates with separate receipt/attempt/fit costs; native parent lifecycle plus exact fit ledger. Platform representative n7 is predeclared, not winner or aggregate.','temporary_directory':str(TMP),'previous_campaign':{'state':fingerprint(PREVIOUS/'docs/harness-state.json'),'fits':35,'prior_cumulative_fits':146,'already_exposed_n':[5,10],'control_source':fingerprint(PREVIOUS/'configs/prepared-inputs.json')},'reused_candidates':[5,10],'run_priority':[int(v.removeprefix('quantile')) for v in VARIANTS],'timing_estimate':{'historical_equal_count_10fit_minutes':[108.0,97.2],'expected_fit_minutes':515,'preparation_inference_evaluation_review_minutes':65,'expected_total_hours':9.67,'hard_stop_new_fit_rule':'Remaining time must cover fit plus 45min closeout; new whole candidate also reserves canonical evaluation. Budget can stop unstarted/partial candidates truthfully.'}}
    write(BASE/'configs/frozen-study.json',study)
    meta={'schema_version':2,'entity_type':'experiment','kind':'model','track':'all_a','exp_id':EID,'archive_path':str(BASE.relative_to(ROOT)),'experiment_type':'training_target','title':'等样本分档数扩展 · H20／patience50','change_summary':'新增n=3/7/15/20/30/50，复用n=5/10与连续标签对照；只改等样本分档数。','comparison_baseline':{'ref':study['formal_baseline'],'version':'v2'},'activity':'model_research','role':'experiment','changed_axes':['label_bin_count']}
    write(BASE/'metadata.json',meta)
    env={'python':sys.version,'executable':sys.executable,'platform':platform.platform(),'git_head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'initial_git_status':subprocess.check_output(['git','status','--short'],cwd=ROOT,text=True),'packages':{n:importlib.metadata.version(n) for n in ['numpy','pandas','lightgbm','scipy','pyqlib']},'modules':{n:str(m.__file__) for n,m in [('numpy',numpy),('lightgbm',lightgbm),('qlib',qlib)]},'lightgbm_binaries':[fingerprint(p) for p in Path(lightgbm.__file__).parent.rglob('*') if p.suffix in ['.dylib','.so']]}
    write(BASE/'docs/environment.json',env)
    for p in [TMP/'common.py',TMP/'setup.py',TMP/'bootstrap.py']:save_source(p)
    # Preserve all prior immutable scientific inputs, excluding prior mutable reports.
    files=[ROOT/x['path'] if not Path(x['path']).is_absolute() else Path(x['path']) for x in previous['inputs']]
    files += [PREVIOUS/'configs/prepared-inputs.json',PREVIOUS/'docs/provider-inputs.json.gz',PREVIOUS/'docs/harness-state.json',PREVIOUS/'data/control_new.pkl',PREVIOUS/'data/control_old.pkl']
    for v in REUSED:
        for t in ['new','old']:
            proof=PREVIOUS/'docs'/f'predictions-{v}-{t}.json';files.append(proof)
            for c in read(proof)['components']:
                for k in ['model','prediction']:check(c[k]);files.append(ROOT/c[k]['path'])
            for k in ['ensemble']:check(read(proof)[k]);files.append(ROOT/read(proof)[k]['path'])
            files += [PREVIOUS/'metrics'/f'{v}-{t}.json',PREVIOUS/'data'/f'{v}-{t}-formal-heads.json',PREVIOUS/'data'/f'{v}-{t}-ensemble-heads.json']
    for p in [BASE/'configs/frozen-study.json',BASE/'configs/evaluation.yaml',BASE/'docs/environment.json',BASE/'docs/adapter-common.json']:files.append(p)
    files=list(dict.fromkeys(files))
    plan={'schema_version':2,'campaign_id':'quantile-n-p50-20261107-v1','idea':study['user_idea'],'track':'all_a_model','direction':'training-target','anchor_exp_id':EID,'archive_path':str(BASE.relative_to(ROOT)),'baseline_ref':study['formal_baseline'],'allowed_changes':['label_bin_count'],'selection_rule':study['decision_rule'],'data_version':version,'inputs':[str(p) for p in files],'seeds':SEEDS,'budget':{'max_rounds':3,'max_variants':6,'max_attempts_per_variant':2,'max_wall_hours':10,'max_no_new_evidence_rounds':2,'concurrency':1},'execution_budget':{'max_model_fits':52,'new_label_horizons':[20]},'scientific_candidate_count':6,'paired_control':study['paired_control'],'temporary_directory':str(TMP),'known_native_scope_gap':study['entry_policy'],'previous_campaign':study['previous_campaign']}
    write(BASE/'configs/harness-plan.json',plan)
    r=subprocess.run([sys.executable,str(ROOT/'backtest/scripts/maintenance/experiment_harness.py'),'init','--plan',str(BASE/'configs/harness-plan.json')],capture_output=True,text=True,cwd=ROOT)
    if r.returncode:raise RuntimeError(r.stdout+r.stderr)
    write(PROGRESS,{'status':'preparing','scientific_candidates':{v:{'status':'planned','treatments':{}} for v in VARIANTS},'prior_fit_count':PRIOR_FITS,'jobs':[],'frozen_study':fingerprint(BASE/'configs/frozen-study.json'),'reused_candidates':REUSED})
    state=read(STATE)
    print(json.dumps({'archive':str(BASE),'deadline_local':datetime.datetime.fromtimestamp(state['deadline']).isoformat(),'budget':study['budget']},ensure_ascii=False),flush=True)

def harness_previous_status():
    r=subprocess.run([sys.executable,str(ROOT/'backtest/scripts/maintenance/experiment_harness.py'),'status','--state',str(PREVIOUS/'docs/harness-state.json')],capture_output=True,text=True,cwd=ROOT)
    assert r.returncode==0,r.stderr
    return json.loads(r.stdout)

if __name__=='__main__':main()
